function fixture(string $prefix): array { $files=glob(__DIR__.'/../fixtures/valid/'.$prefix.'*.json');return json_decode(file_get_contents($files[0]),true,512,JSON_THROW_ON_ERROR); }
function simulation(string $prefix,array $context=array()): Simulator {return new Simulator((new DefinitionCompiler())->compile(fixture($prefix)),array_merge(array('created_at'=>'2026-10-12T11:00:00Z','timezone'=>'America/Argentina/Buenos_Aires'),$context));}
function eq($a,$b,string $label='assertion'): void { TraceOracle::same($a,$b,$label); }
function rejects(callable $action,string $message): void {try{$action();}catch(Throwable $e){if(strpos($e->getMessage(),$message)!==false)return;throw $e;}throw new RuntimeException('Expected rejection '.$message);}
function command(Simulator $s,string $kind,array $data=array(),?string $id=null): array {return $s->dispatch(array('id'=>$id??$kind.'_'.count($s->trace()).'_'.substr(hash('sha256',EIPSI\StudyEngine\Contracts\Canonical::json($data)),0,8),'kind'=>$kind,'data'=>$data));}
function nodeIndex(array $d,string $id): int {foreach($d['nodes'] as $i=>$n)if($n['id']===$id)return $i;throw new RuntimeException('Missing node '.$id);}
function mutateNode(array $d,string $id,callable $edit): array {$i=nodeIndex($d,$id);$d['nodes'][$i]=$edit($d['nodes'][$i]);return $d;}
function slots(array $r,string $anchor='2026-10-12T11:00:00Z',string $zone='America/Argentina/Buenos_Aires',?string $horizon=null): array{return iterator_to_array((new RecurrenceMaterializer())->slots($r,$anchor,$zone,$horizon));}

