    $copy=$g->graph();$copy['nodes']['M_ROOT']['position']=999;eq(0,$g->node('M_ROOT')['position']);foreach(array('containment','traversal','temporal','condition','jump','wait','recurrence') as $type)if(!array_key_exists($type,$g->graph()['edges']))throw new RuntimeException('Missing edge type');
});
