$reference=array('kind'=>'QUESTION','node_id'=>'Q_TEST','occurrence_selector'=>array('kind'=>'SINGLE'));
function typed_value($value): array {return array('kind'=>'VALUE','type'=>is_bool($value)?'BOOLEAN':(is_int($value)?'INTEGER':(is_float($value)?'NUMBER':($value===null?'NULL':'STRING'))),'value'=>$value);}
function truth_ast(string $truth): array {global $reference;if($truth==='UNKNOWN')return array('op'=>'EQ','left'=>array('kind'=>'REFERENCE','reference'=>$reference),'right'=>array('kind'=>'VALUE','type'=>'INTEGER','value'=>1));return array('op'=>'EQ','left'=>array('kind'=>'VALUE','type'=>'INTEGER','value'=>1),'right'=>array('kind'=>'VALUE','type'=>'INTEGER','value'=>$truth==='TRUE'?1:2));}
foreach(array('TRUE','FALSE','UNKNOWN') as $a){
    check_case('Kleene NOT '.$a,static function()use($a){eq($a==='UNKNOWN'?$a:($a==='TRUE'?'FALSE':'TRUE'),(new PredicateEvaluator())->evaluate(array('op'=>'NOT','arg'=>truth_ast($a)),static function(){return array('present'=>false,'value'=>null);}));});
    foreach(array('TRUE','FALSE','UNKNOWN') as $b)foreach(array('AND','OR') as $op)check_case('Kleene '.$a.' '.$op.' '.$b,static function()use($a,$b,$op){$expected=$op==='AND'?(in_array('FALSE',array($a,$b),true)?'FALSE':(in_array('UNKNOWN',array($a,$b),true)?'UNKNOWN':'TRUE')):(in_array('TRUE',array($a,$b),true)?'TRUE':(in_array('UNKNOWN',array($a,$b),true)?'UNKNOWN':'FALSE'));eq($expected,(new PredicateEvaluator())->evaluate(array('op'=>$op,'args'=>array(truth_ast($a),truth_ast($b))),static function(){return array('present'=>false,'value'=>null);}));});
}
check_case('Strict comparisons never coerce false, zero, numeric strings or null',static function(){foreach(array(array(false,0),array('1',1),array(null,false),array(1,1.0)) as $pair){eq('FALSE',(new PredicateEvaluator())->evaluate(array('op'=>'EQ','left'=>typed_value($pair[0]),'right'=>typed_value($pair[1])),static function(){throw new RuntimeException('No lookup');}));}});
foreach(array('GT','GTE','LT','LTE','NEQ') as $op)check_case('Comparison '.$op,static function()use($op){eq(in_array($op,array('GT','GTE','NEQ'),true)?'TRUE':'FALSE',(new PredicateEvaluator())->evaluate(array('op'=>$op,'left'=>typed_value(3),'right'=>typed_value(2)),static function(){throw new RuntimeException('No lookup');}));});
