/** Complete a protocol with valid answers and clock changes; this covers traces ending mid-study. */
function complete_remaining(Simulator $s): void {
    for($step=0;$step<300;++$step){$next=$s->nextAction();$kind=$next['kind'];
        if(in_array($kind,array('FINISHED','WITHDRAWN','TERMINATED'),true))return;
        if($kind==='WAIT'){if($next['payload']['until']===null)throw new RuntimeException('Unresolved wait in end-to-end');command($s,'ADVANCE_TIME',array('at'=>$next['payload']['until']));continue;}
        if($kind!=='OPEN_ASSESSMENT')throw new RuntimeException('Unexpected action '.$kind);
        $id=$next['payload']['assessment_execution_id'];command($s,'OPEN_ASSESSMENT',array('block_execution_id'=>$id));$answers=array();
        foreach($s->presentation($id)['pages'] as $page)foreach($page as $question){$n=$s->compiled()->node($question);if($n['kind']!=='QUESTION'||isset($s->snapshot()['coverage'][$id][$question]))continue;
            $value=$n['type']==='BOOLEAN'?true:($n['type']==='CHOICE'?$n['options'][0]['id']:($n['type']==='TEXT'?'done':($n['validation']['min']??1)));$answers[$question]=$value;
        }command($s,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$id,'responses'=>$answers));
    }throw new RuntimeException('End-to-end safety cap exceeded');
}
