check_case('Consent annotation without rule warns and has no automatic termination',static function(){$d=fixture('02');$d['condition_rules']=array();$g=(new DefinitionCompiler())->compile($d);eq('CONSENT_WITHOUT_DECLINE_RULE',$g->graph()['diagnostics'][0]['code']);$s=new Simulator($g,array('created_at'=>'2026-10-12T11:00:00Z'));command($s,'ANSWER',array('question_id'=>'Q_CONSENT','value'=>'NO'));eq('ACTIVE',$s->snapshot()['execution']['state']);});
check_case('Detectable completion rule overlap warns, preserving defined precedence',static function(){$d=fixture('08');$rule=$d['condition_rules'][0];$rule['id']='R_ALSO_CONTINUE';$rule['action']='CONTINUE';$rule['order']=20;$rule['target']=null;$rule['resume_target']=null;$rule['on_target_unavailable']=null;$d['condition_rules'][]=$rule;$g=(new DefinitionCompiler())->compile($d);eq(true,in_array('COMPLETION_RULES_OVERLAP',array_column($g->graph()['diagnostics'],'code'),true));$s=new Simulator($g,array('created_at'=>'2026-10-12T11:00:00Z'));command($s,'SUBMIT_ASSESSMENT',array('node_id'=>'E_FOLLOWUP_1','responses'=>array('Q_RISK'=>9)));eq('WAIT',$s->nextAction()['kind']);$events=array_values(array_filter($s->trace(),static function($e){return $e['type']==='CONDITIONS_EVALUATED';}));eq(array('R_ALSO_CONTINUE'),$events[0]['payload']['suppressed']);});
check_case('RCT optional reference is UNKNOWN with warning, never a fabricated value',static function(){$d=fixture('06');$rule=$d['condition_rules'][0];$rule['id']='R_OPTIONAL_REFERENCE';$rule['predicate']['left']['reference']['node_id']='Q_INTERVENTION_B';$rule['predicate']['right']=typed_value(1);$d['condition_rules'][0]=$rule;$g=(new DefinitionCompiler())->compile($d);eq(true,in_array('OPTIONAL_REFERENCE',array_column($g->graph()['diagnostics'],'code'),true));$s=new Simulator($g,array('created_at'=>'2026-10-12T11:00:00Z'));command($s,'SUBMIT_ASSESSMENT',array('node_id'=>'E_SCREEN','responses'=>array('Q_ELIGIBLE'=>true)));$events=array_values(array_filter($s->trace(),static function($e){return $e['type']==='CONDITIONS_EVALUATED';}));eq('UNKNOWN',$events[0]['payload']['evaluations'][0]['truth']);});
check_case('Same-definition future WAIT preserves completed source, skips only prior opportunities',static function(){
    $d=fixture('04');$rule=fixture('08')['condition_rules'][0];$rule['source']=array('kind'=>'BLOCK','node_id'=>'E_DIARY','occurrence_selector'=>array('kind'=>'FIRST_COMPLETED'));$rule['predicate']=truth_ast('TRUE');$path=array(array('block_id'=>'M_ROOT','slot'=>'single'),array('block_id'=>'E_DIARY','slot'=>array('day'=>5,'slot'=>1)));$rule['target']=array('kind'=>'ASSESSMENT_ENTRY','node_id'=>'E_DIARY','occurrence_selector'=>array('kind'=>'EXACT_OCCURRENCE','occurrence_key'=>$path));$rule['resume_target']=array('kind'=>'QUESTION','node_id'=>'Q_MOOD','occurrence_selector'=>array('kind'=>'EXACT_OCCURRENCE','occurrence_key'=>$path));$d['condition_rules']=array($rule);$s=new Simulator((new DefinitionCompiler())->compile($d),array('created_at'=>'2026-10-12T11:00:00Z'));command($s,'SUBMIT_ASSESSMENT',array('node_id'=>'E_DIARY','slot'=>array('day'=>1,'slot'=>1),'at'=>'2026-10-12T23:00:00Z','responses'=>array('Q_MOOD'=>4)));eq('COMPLETED',$s->instance('E_DIARY',array('day'=>1,'slot'=>1))['state']);eq(false,isset($s->snapshot()['coverage'][$s->instance('E_DIARY',array('day'=>1,'slot'=>1))['id']]['Q_MOOD']));foreach(array(2,3,4) as $day)eq('SKIPPED_BY_RULE',$s->instance('E_DIARY',array('day'=>$day,'slot'=>1))['state']);eq('SCHEDULED',$s->instance('E_DIARY',array('day'=>6,'slot'=>1))['state']);command($s,'ADVANCE_TIME',array('at'=>'2026-10-16T23:00:00Z'));eq('Q_MOOD',$s->snapshot()['cursor']['node_id']);complete_remaining($s);eq(4,$s->outcome()['completed']);eq(3,$s->outcome()['skipped']);
});
check_case('Sequential overlapping windows keep later occurrence traversal BLOCKED without extending times',static function(){$d=mutateNode(fixture('04'),'E_DIARY',static function($n){$n['schedule']['window']['duration']['seconds']=172800;return $n;});$s=new Simulator((new DefinitionCompiler())->compile($d),array('created_at'=>'2026-10-12T11:00:00Z'));eq('WAITING',$s->snapshot()['execution']['state']);command($s,'ADVANCE_TIME',array('at'=>'2026-10-13T23:00:00Z'));eq('AVAILABLE',$s->instance('E_DIARY',array('day'=>1,'slot'=>1))['state']);$second=$s->instance('E_DIARY',array('day'=>2,'slot'=>1));eq('BLOCKED',$second['state']);eq('2026-10-13T23:00:00Z',$second['available_at']);command($s,'SUBMIT_ASSESSMENT',array('node_id'=>'E_DIARY','slot'=>array('day'=>1,'slot'=>1),'responses'=>array('Q_MOOD'=>4)));eq('AVAILABLE',$s->instance('E_DIARY',array('day'=>2,'slot'=>1))['state']);eq($second['due_at'],$s->instance('E_DIARY',array('day'=>2,'slot'=>1))['due_at']);});
